package com.example.yuejie;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;
/** Exactly the reference recording's OS input coordinates and gesture durations. */
public final class MatchedCapture extends TurnChecks {
 public void onStart(){String key=args.getString("mode","cover");output=new File(getTargetContext().getFilesDir(),"matched-turn-evidence");output.mkdirs();Bundle result=new Bundle();Throwable failure=null;try{originalPrefs=new JSONObject(getTargetContext().getSharedPreferences("ReaderActivity",0).getAll());db=new LocalLibrary(getTargetContext());originalPosition=db.progress(book);launchReader();select(PageTurnMode.parse(key));page(2);shot(key+"-normal");for(float y:new float[]{400,960,1450}){int page=reader.surface.frame.pageIndex;swipe(918,y,180,y,700);SystemClock.sleep(1000);assertTrue(reader.surface.frame.pageIndex==page+1,"matched next at "+y);swipe(180,y,918,y,700);SystemClock.sleep(1000);assertTrue(reader.surface.frame.pageIndex==page,"matched previous at "+y);}swipe(900,1000,820,1000,700);SystemClock.sleep(1000);swipe(900,1000,650,1000,100);SystemClock.sleep(1000);swipe(180,1000,430,1000,100);SystemClock.sleep(1000);swipe(900,1000,900,1000,30);SystemClock.sleep(1000);swipe(180,1000,180,1000,30);SystemClock.sleep(1000);shot(key+"-after");result.putString("stream","PASS matched "+key);}catch(Throwable e){failure=e;result.putString("stream","FAIL "+android.util.Log.getStackTraceString(e));try{shot(key+"-failure");}catch(Exception ignored){}}finally{try{if(reader!=null)ui(()->reader.finish());if(originalPrefs!=null)restorePrefs(originalPrefs);if(originalPosition!=null)db.progress(book,originalPosition.optString("chapter"),originalPosition.optInt("offset"),originalPosition.optInt("index"),originalPosition.optInt("total"),originalPosition.optString("title"));}catch(Exception e){result.putString("stream",e.toString());}}finish(failure==null?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
